// Extract plane coefficients (A, B, C, D) from the plane
const double A = plane.a();
const double B = plane.b();
const double C = plane.c();
const double D = plane.d();

// Project each 3D polygon vertex onto the plane and convert to 2D
std::vector<Kernel::Point_2> projected_points;
for (const auto& coord : polygon_coords) {
    // Construct 3D point from coordinates
    Kernel::Point_3 p(coord[0], coord[1], coord[2]);

    // Compute denominator for projection
    const double denominator = A * A + B * B + C * C;
    if (denominator == 0) {
        continue; // Skip degenerate plane
    }

    // Project point onto plane
    const double numerator = A * p.x() + B * p.y() + C * p.z() + D;
    const double scale = numerator / denominator;

    Kernel::Point_3 projected_3d = p - Kernel::Point_3(A, B, C) * scale;

    // Convert the projected point to 2D coordinates
    // Use x and y coordinates (assuming projection to xy-plane or similar)
    projected_points.emplace_back(projected_3d.x(), projected_3d.y());
}

// Insert the polygon as a constrained Delaunay triangulation
Triangulation::Vertex_handle prev = nullptr;
for (size_t i = 0; i < projected_points.size(); ++i) {
    Triangulation::Vertex_handle vh = triangulation.insert(projected_points[i]);
    if (prev) {
        triangulation.insert_constraint(vh, prev);
    }
    prev = vh;
}
if (projected_points.size() > 0) {
    // Close the polygon by adding a constraint from last to first vertex
    triangulation.insert_constraint(prev, triangulation.vertex(projected_points[0]));
}

// Update walk_start for next insertion
walk_start = triangulation.locate(prev);
