const double A = plane.a();
const double B = plane.b();
const double C = plane.c();
const double D = plane.d();

// Project each 3D polygon vertex onto the plane and convert to 2D
std::vector<Kernel::Point_2> projected_points;
for (const auto& coord : polygon_coords) {
    Kernel::Point_3 p(coord[0], coord[1], coord[2]);

    // Compute denominator for projection
    const double denominator = A * A + B * B + C * C;
    if (std::abs(denominator) < 1e-10) {
        continue; // Skip degenerate plane
    }

    // Compute projection scalar
    const double scalar = (A * p[0]() + B * p[1]() + C * p[2]() + D) / denominator;

    // Project point onto plane
    const Kernel::Point_3 projected_3d =
        p - Kernel::Point_3(A * scalar, B * scalar, C * scalar);

    // Use x and y coordinates as 2D points
    projected_points.emplace_back(projected_3d.x(), projected_3d.y());
}

// Insert polygon constraints into the triangulation
std::vector<Triangulation::Vertex_handle> vertices;
for (const auto& point : projected_points) {
    vertices.push_back(triangulation.insert(point));
}

// Close the polygon by adding constraints
if (!vertices.empty()) {
    for (size_t i = 0; i < vertices.size(); ++i) {
        const size_t next = (i + 1) % vertices.size();
        triangulation.insert_constraint(vertices[i], vertices[next]);
    }
}

// Update walk_start for next insertion
if (!vertices.empty()) {
    walk_start = triangulation.locate(vertices[0]);
}
