    // Project point onto plane
    Kernel::Point_3 projected_3d = p - Kernel::Point_3(A*scalar, B*scalar, C*scalar);

    // Use x and y coordinates as 2D points
    projected_points.emplace_back(projected_3d.x(), projected_3d.y());
}

// Insert polygon vertices and constraints into the triangulation
if (!projected_points.empty()) {
    std::vector<Triangulation::Vertex_handle> vertices;
    for (const auto& point : projected_points) {
        vertices.push_back(triangulation.insert(point));
    }

    // Add edges between consecutive vertices to form polygon constraints
    for (size_t i = 0; i < vertices.size(); ++i) {
        size_t j = (i + 1) % vertices.size();
        triangulation.insert_constraint(vertices[i], vertices[j]);
    }

    // Set walk_start to the first vertex's face if vertices exist
    if (!vertices.empty()) {
        walk_start = vertices[0]->face();
    }
}
